SELECT p.gender, COUNT(DISTINCT a.subject_id) AS patient_count, COUNT(DISTINCT a.hadm_id) AS admission_count, AVG(l.value) AS average_hs_tn_t, MEDIAN(l.value) AS median_hs_tn_t, (percentile_cont(0.75) within GROUP (ORDER BY l.value) - percentile_cont(0.25) within GROUP (ORDER BY l.value)) AS interquartile_range FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 50 AND 60 AND (l.value > 0.014 OR (l.value = 0.014 AND l.itemid IN (SELECT itemid FROM d_labitems WHERE category = 'hs-tn-t'))) AND (a.admission_type_id IN (SELECT admission_type_id FROM admissions WHERE admission_type_code IN ('CH','AMI')) OR (a.admission_type_id IN (SELECT admission_type_id FROM admissions WHERE admission_type_code = 'ACC') AND l.value > 0.014)) GROUP BY p.gender;